/**
 * @civ/content — versioned content packs consumed by the engine.
 *
 * Season one ships one authored pack (`civ.season_one`): five fictional
 * cultures, their constructed-language name datasets with a fallback chain,
 * and a pre-industrial demography table (docs/POPULATION.md). The pack is
 * generated by `scripts/build-season-one.mjs` and frozen; its canonical
 * digest is the world's `contentVersion`.
 */
import { contentPackSchema, parseContract, type ContentPack, type Digest } from "@civ/contracts";
import { canonicalHash } from "@civ/domain";
import seasonOneData from "./packs/season-one.json" with { type: "json" };
import { assertValidContentPack } from "./validate.js";

export * from "./validate.js";

function load(data: unknown): ContentPack {
  const pack = parseContract("content pack", contentPackSchema, data);
  assertValidContentPack(pack);
  return Object.freeze(pack);
}

/** The season-one content pack, schema- and semantically validated at load. */
export const SEASON_ONE_PACK: ContentPack = load(seasonOneData);

/** Digest of a content pack set: the `contentVersion` of every world using it. */
export function contentVersionOf(packs: readonly ContentPack[]): Digest {
  return canonicalHash({
    packs: [...packs]
      .map((pack) => ({ packId: pack.packId, version: pack.version, digest: canonicalHash(pack) }))
      .sort((a, b) => (a.packId < b.packId ? -1 : a.packId > b.packId ? 1 : 0)),
  });
}

export const SEASON_ONE_CONTENT_VERSION: Digest = contentVersionOf([SEASON_ONE_PACK]);

/** Content packs bundled with this build, as `<packId>@<version>`. */
export const BUNDLED_CONTENT_PACKS: readonly string[] = Object.freeze([
  `${SEASON_ONE_PACK.packId}@${SEASON_ONE_PACK.version}`,
]);
